import {deflateSync} from 'node:zlib';import {keyOf,scramble} from '../../src/core/ttt2/archive-codec.mjs';import {ttt2Fixture} from './ttt2.mjs';
export function archiveFixture({compressed=true,extra=false}={}){const assets=ttt2Fixture(),entries=assets.map((r,i)=>({key:keyOf('jin.'+['nud','nut','bon'][i]),bytes:Buffer.from(r.data)}));if(extra)entries.push({key:1234,bytes:Buffer.from('authored unrelated entry')});const payload=[];let at=0;const offsets=[];for(const r of entries){let b=r.bytes;if(compressed){const header=Buffer.alloc(16);header.write('NRCZ');header.writeUInt32BE(b.length,4);b=Buffer.concat([header,deflateSync(b)]);}const stored=scramble(b,r.key);offsets.push(at+(stored.length%16));payload.push(stored,Buffer.alloc((16-stored.length%16)%16));at+=Math.ceil(stored.length/16)*16;}offsets.push(at);const info=Buffer.alloc(8+entries.length*8),data=Buffer.alloc(8+offsets.length*4);info.writeUInt32BE(info.length);info.write('ofsi',4);data.writeUInt32BE(data.length);data.write('ofsd',4);entries.forEach((r,i)=>{info.writeUInt32BE(r.key,8+i*8);info.writeUInt32BE(i+20,12+i*8);});offsets.forEach((o,i)=>data.writeUInt32BE(o,8+i*4));return{ofs:Buffer.concat([info,data]),bin:Buffer.concat([Buffer.alloc(256),...payload]),assets,entries};}
